import React, { useState } from 'react';

function AdminPanel({
  users = [],
  movies = [],
  showtimes = [],
  rooms = [],
  bookings = [],
  onCancelBooking,
  onCancelOrder,
  onAddShowtime,
  onManageMovies,
  onBackHome,
}) {
  const [newShowtime, setNewShowtime] = useState({ movie_id: '', room_id: '', show_date: '', show_time: '', ticket_price: '' });

  const movieOptions = movies.map(movie => ({ value: movie.id, label: movie.title }));
  const roomOptions = rooms.map(room => ({ value: room.id, label: room.name }));

  const groupedBookings = bookings.reduce((acc, b) => {
    const key = b.original_booking_id || b.id;
    acc[key] = acc[key] || [];
    acc[key].push(b);
    return acc;
  }, {});

  const handleAddShowtime = (e) => {
    e.preventDefault();
    if (!newShowtime.movie_id || !newShowtime.room_id || !newShowtime.show_date || !newShowtime.show_time || !newShowtime.ticket_price) {
      alert('Vui lòng nhập đầy đủ thông tin suất chiếu.');
      return;
    }
    onAddShowtime({
      ...newShowtime,
      id: `st-${Date.now()}`,
      ticket_price: Number(newShowtime.ticket_price)
    });
    setNewShowtime({ movie_id: '', room_id: '', show_date: '', show_time: '', ticket_price: '' });
  };

  return (
    <div style={{ maxWidth: 1180, margin: '0 auto', padding: '0 16px' }}>
      <div className="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4" style={{ padding: '16px 0' }}>
        <div>
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: 10, marginBottom: 8, padding: '6px 14px', borderRadius: 999, background: 'rgba(124, 58, 237, 0.14)', color: '#d8b4fe', fontSize: '0.85rem', fontWeight: 700 }}>
            ADMIN MODE
          </div>
          <h2 className="fw-bold mb-2" style={{ color: '#f8fafc', fontSize: '2rem' }}>Bảng điều khiển quản trị</h2>
          <p className="mb-0" style={{ color: '#cbd5e1', maxWidth: 560, fontSize: '0.98rem' }}>Quản lý phim, suất chiếu và đơn vé với giao diện đồng bộ, hiện đại và dễ sử dụng.</p>
        </div>
        <div className="d-flex flex-wrap gap-2">
          <button
            className="btn fw-bold text-white"
            style={{
              borderRadius: 18,
              background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)',
              border: 'none',
              padding: '12px 22px',
              fontSize: '0.98rem',
              boxShadow: '0 18px 42px rgba(124, 58, 237, 0.16)'
            }}
            onClick={onManageMovies}
          >
            Quản lý phim
          </button>
          <button className="btn fw-bold" style={{ borderRadius: 18, background: 'rgba(255,255,255,0.08)', color: '#e5e7eb', border: '1px solid rgba(255,255,255,0.14)', padding: '12px 22px', fontSize: '0.98rem' }} onClick={onBackHome}>Về trang chủ</button>
        </div>
      </div>

      <div className="row gy-4">
        <div className="col-12 col-lg-4">
          <div className="card custom-card p-4 shadow-sm" style={{ borderRadius: 24, minHeight: 220, background: 'rgba(15, 23, 42, 0.96)' }}>
            <h5 className="fw-bold mb-4" style={{ color: '#c4b5fd', fontSize: '1.05rem' }}>Thống kê nhanh</h5>
            <div className="d-flex justify-content-between align-items-center mb-3"><span className="text-secondary">Người dùng</span><strong style={{ fontSize: '1rem' }}>{users.length}</strong></div>
            <div className="d-flex justify-content-between align-items-center mb-3"><span className="text-secondary">Phim</span><strong style={{ fontSize: '1rem' }}>{movies.length}</strong></div>
            <div className="d-flex justify-content-between align-items-center mb-3"><span className="text-secondary">Suất chiếu</span><strong style={{ fontSize: '1rem' }}>{showtimes.length}</strong></div>
            <div className="d-flex justify-content-between align-items-center"><span className="text-secondary">Đơn vé</span><strong style={{ fontSize: '1rem' }}>{Object.keys(groupedBookings).length}</strong></div>
          </div>
        </div>

        <div className="col-12 col-lg-8">
          <div className="card custom-card p-3 shadow-sm mb-4" style={{ borderRadius: 22 }}>
            <h5 className="fw-bold mb-3" style={{ color: '#c4b5fd' }}>Tạo suất chiếu mới</h5>
            <form onSubmit={handleAddShowtime}>
              <div className="row g-3">
                <div className="col-12 col-md-6">
                  <select className="form-select" value={newShowtime.movie_id} onChange={(e) => setNewShowtime(prev => ({ ...prev, movie_id: e.target.value }))}>
                    <option value="">Chọn phim</option>
                    {movieOptions.map(opt => <option key={opt.value} value={opt.value}>{opt.label}</option>)}
                  </select>
                </div>
                <div className="col-12 col-md-6">
                  <select className="form-select" value={newShowtime.room_id} onChange={(e) => setNewShowtime(prev => ({ ...prev, room_id: e.target.value }))}>
                    <option value="">Chọn phòng</option>
                    {roomOptions.map(opt => <option key={opt.value} value={opt.value}>{opt.label}</option>)}
                  </select>
                </div>
                <div className="col-6">
                  <input type="date" className="form-control" value={newShowtime.show_date} onChange={(e) => setNewShowtime(prev => ({ ...prev, show_date: e.target.value }))} />
                </div>
                <div className="col-6">
                  <input type="time" className="form-control" value={newShowtime.show_time} onChange={(e) => setNewShowtime(prev => ({ ...prev, show_time: e.target.value }))} />
                </div>
                <div className="col-12 col-md-6">
                  <input type="number" min="0" className="form-control" placeholder="Giá vé" value={newShowtime.ticket_price} onChange={(e) => setNewShowtime(prev => ({ ...prev, ticket_price: e.target.value }))} />
                </div>
                <div className="col-12 col-md-6 d-grid">
                  <button type="submit" className="btn fw-bold text-white" style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)', borderRadius: 10, padding: '10px 18px' }}>Lưu suất chiếu</button>
                </div>
              </div>
            </form>
          </div>

          <div className="card custom-card p-3 shadow-sm" style={{ borderRadius: 22 }}>
            <h5 className="fw-bold mb-4" style={{ color: '#c4b5fd' }}>Danh sách đơn vé</h5>
            {Object.keys(groupedBookings).length === 0 && <p className="text-secondary">Chưa có đơn vé nào.</p>}
            {Object.entries(groupedBookings).map(([groupId, group]) => {
              const first = group[0];
              const orderUser = users.find(u => u.id === first.user_id);
              return (
                <div key={groupId} className="p-3 mb-3" style={{ borderRadius: 18, background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.08)' }}>
                  <div className="d-flex justify-content-between align-items-start flex-wrap gap-3">
                    <div style={{ minWidth: 220 }}>
                      <div className="fw-bold" style={{ color: '#f8fafc', fontSize: '0.98rem' }}>Đơn {groupId}</div>
                      <div className="text-secondary small">Người dùng: {orderUser?.username || 'Khách'}</div>
                      {orderUser && (
                        <>
                          <div className="text-secondary small">Email: {orderUser.email}</div>
                          <div className="text-secondary small">Vai trò: {orderUser.role}</div>
                        </>
                      )}
                      <div className="text-secondary small">Trạng thái: {first.paid ? 'Đã thanh toán' : 'Chưa thanh toán'}</div>
                    </div>
                    <div className="d-flex gap-2 flex-wrap" style={{ justifyContent: 'flex-end' }}>
                      <button className="btn btn-sm fw-bold" style={{ background: '#ef4444', color: '#fff', borderRadius: 12, padding: '10px 16px' }} onClick={() => onCancelOrder(groupId)}>Hủy đơn</button>
                    </div>
                  </div>
                  <div className="mt-3 small" style={{ color: '#cbd5e1' }}>Ghế: {group.map(b => b.seat_id).join(', ')}</div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

export default AdminPanel;
